const aNav=document.getElementById('navMenuAccount');const spanPage=document.createElement('span');spanPage.innerHTML=aNav.innerHTML;spanPage.className=aNav.className+' active';spanPage.id=aNav.id;spanPage.setAttribute('aria-current','page');aNav.replaceWith(spanPage);document.addEventListener('DOMContentLoaded',function(){const editBtn=document.getElementById('editBtn');const saveBtn=document.getElementById('saveBtn');const editableInputs=document.querySelectorAll('#profileForm input:not(#email, #username)');if(editBtn){editBtn.addEventListener('click',function(){editableInputs.forEach((input)=>{input.removeAttribute('readonly')});const nameInput=document.getElementById('name');if(nameInput)nameInput.focus();editBtn.setAttribute('disabled','true');saveBtn.removeAttribute('disabled')})}})